library(shiny)
library(bslib)
library(RSQLite)
library(DBI)
library(httr)
library(jsonlite)
library(DT)
library(dplyr)
library(tidyr)
library(shinyTree) 

BASE_URL <- "https://canvas.its.virginia.edu/api/v1/"

# --- DATABASE OVERHAUL ---
init_db <- function() {
  con <- dbConnect(RSQLite::SQLite(), "local_gradebook.sqlite")
  
  dbExecute(con, "CREATE TABLE IF NOT EXISTS my_classes (id INTEGER PRIMARY KEY AUTOINCREMENT, class_type TEXT, canvas_id TEXT, canvas_name TEXT, custom_name TEXT, description TEXT, color TEXT)")
  
  # Added nickname and notes to the students table
  dbExecute(con, "CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, canvas_user_id TEXT, sortable_name TEXT, nickname TEXT, notes TEXT)")
  
  dbExecute(con, "CREATE TABLE IF NOT EXISTS assignment_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, name TEXT, canvas_weight NUMERIC, local_weight NUMERIC, drop_lowest INTEGER, is_sync INTEGER)")
  dbExecute(con, "CREATE TABLE IF NOT EXISTS assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, group_id INTEGER, canvas_assign_id TEXT, name TEXT, canvas_name TEXT, canvas_group_id INTEGER, scoring_mode TEXT DEFAULT 'negative', never_drop INTEGER DEFAULT 0, canvas_never_drop INTEGER DEFAULT 0)")
  dbExecute(con, "CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY AUTOINCREMENT, assignment_id INTEGER, parent_id INTEGER, title TEXT, max_points NUMERIC, FOREIGN KEY(parent_id) REFERENCES questions(id))")
  dbExecute(con, "CREATE TABLE IF NOT EXISTS rubric_items (id INTEGER PRIMARY KEY AUTOINCREMENT, question_id INTEGER, description TEXT, point_adjustment NUMERIC)")
  dbExecute(con, "CREATE TABLE IF NOT EXISTS subgrades (student_id INTEGER, assignment_id INTEGER, question_id INTEGER, score NUMERIC, PRIMARY KEY(student_id, assignment_id, question_id))")
  
  return(con)
}

color_choices <- c("Cavalier Orange" = "#E57200", "Rotunda Blue" = "#4B7BE5", "Sea Surface Teal" = "#20c997", "Deep Water Navy" = "#3A5A80", "Coral Pink" = "#ff7b9c", "Warm Pad Magenta" = "#e83e8c", "Rhodes Amber" = "#ffc107", "Synthwave Purple" = "#b300ff", "Slate Grey" = "#8d99ae")
custom_theme <- bs_theme(bg = "#12151A", fg = "#E0E0E0", primary = "#20c997", base_font = font_google("Inter"))

ui <- page_fillable(
  theme = custom_theme,
  tags$head(tags$style(HTML("
    body { background-image: radial-gradient(rgba(255, 255, 255, 0.05) 1.5px, transparent 1.5px); background-size: 25px 25px; }
    .modal-content, .card { background-image: none !important; }
    .breadcrumb-link:hover { color: #ffffff !important; transition: 0.2s; }
    .jstree-default .jstree-anchor { color: #E0E0E0 !important; font-family: 'Inter', sans-serif; }
    .jstree-default .jstree-clicked { background: #2a2d35 !important; border: 1px solid #20c997 !important; border-radius: 4px; }
    .split-left { border-right: 1px solid #2a2d35; height: 75vh; overflow-y: auto; padding-right: 15px; }
    .split-right { height: 75vh; overflow-y: auto; padding-left: 15px; }
    /* DT Styling */
    .dataTables_wrapper { color: #E0E0E0;}
    table.dataTable tbody tr { background-color: #1a1d24; color: #E0E0E0; }
    table.dataTable tbody tr:hover { background-color: #2a2d35 !important; }
    table.dataTable thead th { background-color: #12151A; color: #20c997; border-bottom: 2px solid #20c997 !important; font-weight: 700;}
    table.dataTable td { border-color: #2a2d35 !important; }
    /* Fix DataTables FixedColumns Brightness */
    table.dataTable thead tr th.dtfc-fixed-left { background-color: #12151A !important; z-index: 2; border-right: 1px solid #2a2d35; }
    table.dataTable tbody tr td.dtfc-fixed-left { background-color: #1a1d24 !important; z-index: 1; border-right: 1px solid #2a2d35; }
  "))),
  div(style = "position: absolute; top: 25px; right: 25px; z-index: 1000;", uiOutput("api_key_ui")),
  uiOutput("page_content")
)

server <- function(input, output, session) {
  con <- init_db()
  onStop(function() { dbDisconnect(con) })
  
  rv <- reactiveValues(
    page = "home", active_class_id = NULL, active_assign_id = NULL, active_q_id = NULL,
    class_to_delete = NULL, class_to_edit = NULL, my_classes = dbGetQuery(con, "SELECT * FROM my_classes"),
    canvas_cache = NULL, initialized_ids = c(),
    api_status = if(Sys.getenv("CANVAS_API_TOKEN") != "") "found" else "missing",
    refresh_tree = 0, refresh_rubric = 0, refresh_course = 0, refresh_roster = 0, # Added refresh_roster
    initialized_assign_ids = c(), assign_to_edit = NULL, assign_to_delete = NULL,
    initialized_group_ids = c(), group_to_edit = NULL, group_to_delete = NULL,
    student_to_edit = NULL, student_to_delete = NULL # Added student trackers
  )
  
  # --- API MANAGEMENT ---
  output$api_key_ui <- renderUI({
    if (rv$api_status == "found") span(icon("check-circle"), " API Key Found", style="color: #20c997; font-weight: 600; font-size: 0.9em; background: #1a1d24; padding: 8px 12px; border-radius: 20px; border: 1px solid #2a2d35;")
    else actionButton("open_api_modal", "No API Key Detected", icon = icon("key"), class = "btn-warning btn-sm", style="font-weight: 600; border-radius: 20px;")
  })
  observeEvent(input$open_api_modal, { showModal(modalDialog(title = "Set Canvas API Key", passwordInput("api_key_input", "Canvas API Token:"), footer = tagList(modalButton("Cancel"), actionButton("save_api_key", "Save Key", class = "btn-success")))) })
  observeEvent(input$save_api_key, { req(input$api_key_input); Sys.setenv(CANVAS_API_TOKEN = input$api_key_input); writeLines(paste0("CANVAS_API_TOKEN=", input$api_key_input), ".Renviron"); rv$api_status <- "found"; removeModal() })
  api_get <- function(endpoint) {
    token <- Sys.getenv("CANVAS_API_TOKEN")
    req(token != "")
    res <- GET(paste0(BASE_URL, endpoint), add_headers(Authorization = paste("Bearer", token)))
    fromJSON(content(res, "text", encoding = "UTF-8"), flatten = TRUE)
  }  
  # --- UI ROUTER ---
  output$page_content <- renderUI({
    if (rv$page == "home") { build_home_page() } 
    else if (rv$page == "course_home") { build_course_home() }
    else if (rv$page == "assignment_setup") { build_assignment_setup() }
    else if (rv$page == "grading_mode") { build_grading_mode() }
    else if (rv$page == "overall_gradebook") { build_overall_gradebook() }
    else if (rv$page == "roster_view") { build_roster_view() } # <-- NEW ROUTE
  })
  
  # --- DASHBOARD & SYNC (Unchanged) ---
  build_home_page <- function() {
    rv$refresh_course
    cards <- lapply(seq_len(nrow(rv$my_classes)), function(i) {
      row <- rv$my_classes[i, ]
      sub_text <- if(row$class_type == "standalone") "Standalone Gradebook" else paste("Linked to:", row$canvas_name)
      card(
        style = paste0("width: 250px; height: 300px; background-color: #1a1d24; border: 1px solid #2a2d35; border-top: 3px solid ", row$color, "; box-shadow: 0 8px 25px ", row$color, "33; flex-shrink: 0; display: flex; flex-direction: column;"),
        card_header(
          div(style = "display: flex; justify-content: space-between; align-items: center; width: 100%;", span(row$custom_name, style = "overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 700; font-size: 1.15em; color: #ffffff;"),
              div(style = "display: flex; gap: 10px;", actionButton(paste0("edit_", row$id), label=NULL, icon=icon("pen"), class="btn-sm", style="background:transparent; border:none; color:#6c757d; padding:0;"), actionButton(paste0("delete_", row$id), label=NULL, icon=icon("trash"), class="btn-sm", style="background:transparent; border:none; color:#6c757d; padding:0;"))),
          style = "background-color: transparent; border-bottom: 1px solid #2a2d35; flex: 0 0 65px; display: flex; align-items: center;"
        ),
        card_body(
          class = "d-flex flex-column", style = "overflow: hidden; padding: 15px; flex: 1 1 auto;", p(sub_text, style="font-size: 0.85em; color: #8d99ae; flex: 0 0 auto; margin-bottom: 12px;"),
          if (!is.na(row$description) && row$description != "") { div(p(row$description, style="font-size: 0.9em; margin: 0; color: #adb5bd;"), style="overflow-y: auto; flex: 1 1 auto; min-height: 0; margin-bottom: 15px; padding-right: 5px;") } else { div(style="flex: 1 1 auto;") },
          actionButton(paste0("enter_", row$id), "Enter Gradebook", style=paste0("background-color: transparent; border: 1px solid ", row$color, "; color: ", row$color, "; flex: 0 0 auto; margin-top: auto; font-weight: 600;"), class = "w-100")
        )
      )
    })
    add_card <- card(style = "width: 250px; height: 300px; background-color: transparent; border: 2px dashed #495057; box-shadow: none; flex-shrink: 0;", card_body(class = "d-flex justify-content-center align-items-center h-100", actionButton("open_create_modal", "+ Create New Class", style="background: transparent; border: none; color: #adb5bd; font-weight: 600; font-size: 1.2em;", class = "stretch-link")))
    div(class = "p-4", h2("Dashboard", style = "margin-bottom: 1.5rem; color: #ffffff; font-weight: 700;"), div(style = "display: flex; flex-wrap: wrap; gap: 1.5rem;", tagList(cards), add_card))
  }
  
  observe({
    req(nrow(rv$my_classes) > 0)
    new_ids <- setdiff(rv$my_classes$id, rv$initialized_ids)
    if (length(new_ids) > 0) {
      lapply(new_ids, function(id) {
        local({
          current_id <- id
          observeEvent(input[[paste0("enter_", current_id)]], { rv$active_class_id <- current_id; rv$page <- "course_home" }, ignoreInit = TRUE)
          observeEvent(input[[paste0("delete_", current_id)]], { dbExecute(con, "DELETE FROM my_classes WHERE id = ?", params = list(current_id)); rv$my_classes <- dbGetQuery(con, "SELECT * FROM my_classes") }, ignoreInit = TRUE)
          observeEvent(input[[paste0("edit_", current_id)]], { rv$class_to_edit <- current_id; curr_data <- rv$my_classes[rv$my_classes$id == current_id, ]; showModal(modalDialog(title = "Edit Class Info", textInput("edit_custom_name", "Display Name:", value = curr_data$custom_name), textAreaInput("edit_description", "Course Description:", value = curr_data$description, rows = 2), selectInput("edit_color", "Card Color:", choices = color_choices, selected = curr_data$color), footer = tagList(modalButton("Cancel"), actionButton("save_edit_class", "Save Changes", class = "btn-success")))) }, ignoreInit = TRUE)
        })
      })
      rv$initialized_ids <- c(rv$initialized_ids, new_ids)
    }
  })
  
  observeEvent(input$save_edit_class, { req(input$edit_custom_name, rv$class_to_edit); dbExecute(con, "UPDATE my_classes SET custom_name = ?, description = ?, color = ? WHERE id = ?", params = list(input$edit_custom_name, input$edit_description, input$edit_color, rv$class_to_edit)); rv$my_classes <- dbGetQuery(con, "SELECT * FROM my_classes"); rv$class_to_edit <- NULL; removeModal() })
  observeEvent(input$open_create_modal, { showModal(modalDialog(title = "Set Up a New Class", radioButtons("modal_class_type", "Class Type:", choices = c("Sync with Canvas" = "canvas", "Standalone" = "standalone"), inline = TRUE), conditionalPanel(condition = "input.modal_class_type == 'canvas'", selectInput("modal_canvas_course", "Canvas Course:", choices = c("Fetching from Canvas..." = ""))), textInput("modal_custom_name", "Display Name:"), textAreaInput("modal_description", "Course Description:", rows = 2), selectInput("modal_color", "Card Color:", choices = color_choices), footer = tagList(modalButton("Cancel"), actionButton("save_new_class", "Create Class", class = "btn-success")))); if(rv$api_status == "found") { tryCatch({ courses <- api_get("courses?enrollment_type=teacher&per_page=100"); valid_courses <- courses[!is.na(courses$name), ]; rv$canvas_cache <- valid_courses; updateSelectInput(session, "modal_canvas_course", choices = setNames(valid_courses$id, valid_courses$name)) }, error = function(e) { updateSelectInput(session, "modal_canvas_course", choices = c("Error fetching courses" = "")) }) } })
  observeEvent(input$save_new_class, { req(input$modal_custom_name); if (input$modal_class_type == "canvas") { req(input$modal_canvas_course); c_name <- rv$canvas_cache$name[rv$canvas_cache$id == as.character(input$modal_canvas_course)]; c_id <- input$modal_canvas_course } else { c_name <- "Standalone"; c_id <- "" }; dbExecute(con, "INSERT INTO my_classes (class_type, canvas_id, canvas_name, custom_name, description, color) VALUES (?, ?, ?, ?, ?, ?)", params = list(input$modal_class_type, c_id, c_name, input$modal_custom_name, input$modal_description, input$modal_color)); rv$my_classes <- dbGetQuery(con, "SELECT * FROM my_classes"); removeModal() })
  
  build_course_home <- function() {
    rv$refresh_course
    active_class <- rv$my_classes[rv$my_classes$id == rv$active_class_id, ]
    is_standalone <- active_class$class_type == "standalone"
    
    groups <- dbGetQuery(con, "SELECT * FROM assignment_groups WHERE course_id = ?", params = list(rv$active_class_id))
    assignments <- dbGetQuery(con, "SELECT * FROM assignments WHERE course_id = ?", params = list(rv$active_class_id))
    
    sync_controls <- if(!is_standalone) {
      tagList(
        actionButton("sync_canvas", "Sync to Canvas", icon = icon("rotate"), style="background-color: #4B7BE5; border: none; color: white;"),
        actionButton("reset_local", "Reset to Canvas Defaults", icon = icon("undo"), style="background-color: transparent; border: 1px solid #8d99ae; color: #8d99ae;")
      )
    } else { NULL }
    
    action_bar <- div(style = "display: flex; gap: 15px; margin-bottom: 2rem; align-items: center; flex-wrap: wrap; width: 100%;",
                      sync_controls,
                      actionButton("open_create_group", "+ Create Assignment Group", icon = icon("folder-plus"), style="background-color: #2a2d35; border: 1px solid #495057; color: #E0E0E0; font-weight: 600;"),
                      actionButton("open_create_assign", "+ Create Assignment", icon = icon("file-medical"), style="background-color: #20c997; border: none; color: #12151A; font-weight: bold;"),
                      
                      # Flex right alignment for both tools
                      div(style = "margin-left: auto; display: flex; gap: 10px;",
                          actionButton("view_roster", "View Roster", icon = icon("users"), style="background-color: #2a2d35; border: 1px solid #495057; color: #E0E0E0; font-weight: 600;"),
                          actionButton("view_full_gradebook", "View Full Gradebook", icon = icon("table"), style="background-color: #2a2d35; border: 1px solid #495057; color: #E0E0E0; font-weight: 600;")
                      )
    )
    
    group_sections <- if(nrow(groups) > 0) {
      lapply(seq_len(nrow(groups)), function(i) {
        g <- groups[i, ]
        g_assigns <- assignments[assignments$group_id == g$id, ]
        
        cards <- lapply(seq_len(nrow(g_assigns)), function(j) {
          a <- g_assigns[j, ]
          
          # NEW: Standalone lock icon (no text)
          lock_icon <- if(!is.na(a$never_drop) && a$never_drop == 1) {
            span(icon("lock"), style="color: #ffc107; font-size: 1.1em;", title="Never Drop")
          } else { NULL }
          
          # Action bar now vertically centers the lock icon alongside the buttons
          card_actions <- div(style = "display: flex; align-items: center; gap: 12px; margin-left: 15px;",
                              lock_icon,
                              actionButton(paste0("edit_assign_", a$id), label = NULL, icon = icon("pen"), class = "btn-sm", style = "background: transparent; border: none; color: #6c757d; padding: 0;"),
                              if (is.na(a$canvas_assign_id) || a$canvas_assign_id == "") {
                                actionButton(paste0("del_assign_", a$id), label = NULL, icon = icon("trash"), class = "btn-sm", style = "background: transparent; border: none; color: #dc3545; padding: 0;")
                              } else { NULL }
          )
          
          # NEW: Fixed height (65px) and flex-centering ensures uniform cards
          card(style = "background-color: #1a1d24; border: 1px solid #2a2d35; border-left: 4px solid #20c997; padding: 0; height: 65px; display: flex; justify-content: center;",
               div(style = "display: flex; justify-content: space-between; align-items: center; padding: 0 15px; width: 100%; height: 100%;",
                   # Clickable area takes up the remaining left space
                   div(style = "cursor: pointer; flex-grow: 1; height: 100%; display: flex; align-items: center;",
                       onclick = sprintf("Shiny.setInputValue('select_assignment', %d, {priority: 'event'});", a$id),
                       div(style="font-weight: 600; color: #ffffff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;", a$name)
                   ),
                   card_actions
               )
          )
        })
        
        div(style = "margin-bottom: 2.5rem;", 
            div(style = "display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid #2a2d35; padding-bottom: 10px; margin-bottom: 15px;",
                h4(paste0(g$name, " (", g$local_weight, "%)"), style = "color: #ffffff; margin: 0; font-weight: 600;"),
                div(style = "display: flex; gap: 10px;",
                    actionButton(paste0("edit_group_", g$id), label=NULL, icon=icon("pen"), class="btn-sm", style="background: transparent; border: none; color: #6c757d; padding: 0;"),
                    if(is_standalone) actionButton(paste0("del_group_", g$id), label=NULL, icon=icon("trash"), class="btn-sm", style="background: transparent; border: none; color: #dc3545; padding: 0;") else NULL
                )
            ),
            if(length(cards) > 0) { div(style = "display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 1rem;", tagList(cards)) } else { p("No assignments in this group yet.", style="color: #6c757d; font-style: italic;") }
        )
      })
    } else {
      div(style="text-align: center; padding: 40px; background: #1a1d24; border: 1px dashed #2a2d35; border-radius: 8px;",
          p("This course is currently empty. Start by creating an assignment group.", style="color: #8d99ae; margin-bottom: 0;")
      )
    }
    
    div(class = "p-4", 
        actionLink("nav_home", "⬅ Dashboard", style="color: #adb5bd; font-weight: 600; margin-bottom: 20px; display: block;"), 
        action_bar, 
        tagList(group_sections)
    )  
    }
  observeEvent(input$nav_home, { rv$page <- "home" })
  observeEvent(input$select_assignment, { rv$active_assign_id <- input$select_assignment; rv$active_q_id <- NULL; rv$page <- "assignment_setup" })
  
  # --- CANVAS SYNC ENGINE ---
  observeEvent(input$sync_canvas, {
    req(rv$active_class_id)
    active_class <- rv$my_classes[rv$my_classes$id == rv$active_class_id, ]
    req(active_class$class_type == "canvas", active_class$canvas_id != "")
    
    showModal(modalDialog("Syncing data from Canvas... Please leave this window open.", footer = NULL))
    prog_id <- showNotification("Initializing sync...", duration = NULL, closeButton = FALSE, type = "message")
    
    tryCatch({
      showNotification("Fetching course architecture...", id = prog_id)
      stu_endpoint <- paste0("courses/", active_class$canvas_id, "/users?enrollment_type[]=student&per_page=100")
      groups_endpoint <- paste0("courses/", active_class$canvas_id, "/assignment_groups?include[]=rules")
      assign_endpoint <- paste0("courses/", active_class$canvas_id, "/assignments?per_page=100")
      
      c_students <- api_get(stu_endpoint)
      c_groups <- api_get(groups_endpoint)
      c_assigns <- api_get(assign_endpoint)
      
      # 1. Sync Students
      showNotification("Syncing Roster...", id = prog_id)
      if (length(c_students) > 0 && nrow(c_students) > 0) {
        for (i in 1:nrow(c_students)) {
          s_id <- as.character(c_students$id[i])
          s_name <- if(!is.null(c_students$sortable_name[i]) && !is.na(c_students$sortable_name[i])) c_students$sortable_name[i] else c_students$name[i]
          
          existing_s <- dbGetQuery(con, "SELECT id FROM students WHERE course_id = ? AND canvas_user_id = ?", params = list(rv$active_class_id, s_id))
          if (nrow(existing_s) > 0) {
            dbExecute(con, "UPDATE students SET sortable_name = ? WHERE id = ?", params = list(s_name, existing_s$id[1]))
          } else {
            dbExecute(con, "INSERT INTO students (course_id, canvas_user_id, sortable_name) VALUES (?, ?, ?)", params = list(rv$active_class_id, s_id, s_name))
          }
        }
      }
      
      # 2. Sync Groups
      showNotification("Syncing Assignment Groups...", id = prog_id)
      if (length(c_groups) > 0 && nrow(c_groups) > 0) {
        for (i in 1:nrow(c_groups)) {
          g_name <- c_groups$name[i]
          g_weight <- if("group_weight" %in% names(c_groups) && !is.na(c_groups$group_weight[i])) as.numeric(c_groups$group_weight[i]) else 0
          g_drop <- if("rules.drop_lowest" %in% names(c_groups) && !is.na(c_groups$rules.drop_lowest[i])) as.numeric(c_groups$rules.drop_lowest[i]) else 0
          
          existing_g <- dbGetQuery(con, "SELECT id FROM assignment_groups WHERE course_id = ? AND name = ?", params = list(rv$active_class_id, g_name))
          if (nrow(existing_g) > 0) {
            dbExecute(con, "UPDATE assignment_groups SET canvas_weight = ?, drop_lowest = ?, is_sync = 1 WHERE id = ?", params = list(g_weight, g_drop, existing_g$id[1]))
          } else {
            dbExecute(con, "INSERT INTO assignment_groups (course_id, name, canvas_weight, local_weight, drop_lowest, is_sync) VALUES (?, ?, ?, ?, ?, 1)", params = list(rv$active_class_id, g_name, g_weight, g_weight, g_drop))
          }
        }
      }
      
      # 3. Sync Assignments
      showNotification("Syncing Assignments...", id = prog_id)
      if (length(c_assigns) > 0 && nrow(c_assigns) > 0) {
        for (i in 1:nrow(c_assigns)) {
          a_id <- as.character(c_assigns$id[i])
          a_name <- c_assigns$name[i]
          c_group_id <- c_assigns$assignment_group_id[i]
          pts <- if("points_possible" %in% names(c_assigns) && !is.na(c_assigns$points_possible[i])) as.numeric(c_assigns$points_possible[i]) else 0
          
          c_group_name_idx <- which(c_groups$id == c_group_id)
          if (length(c_group_name_idx) > 0) {
            g_idx <- c_group_name_idx[1]
            g_name <- c_groups$name[g_idx]
            local_g <- dbGetQuery(con, "SELECT id FROM assignment_groups WHERE course_id = ? AND name = ?", params = list(rv$active_class_id, g_name))
            
            if (nrow(local_g) > 0) {
              l_g_id <- local_g$id[1]
              is_never_drop <- 0
              if ("rules.never_drop" %in% names(c_groups)) {
                nd_list <- c_groups$rules.never_drop[[g_idx]]
                if (!is.null(nd_list) && (as.numeric(a_id) %in% as.numeric(nd_list))) {
                  is_never_drop <- 1
                }
              }
              
              existing_a <- dbGetQuery(con, "SELECT id FROM assignments WHERE course_id = ? AND canvas_assign_id = ?", params = list(rv$active_class_id, a_id))
              
              l_a_id <- NULL
              if (nrow(existing_a) > 0) {
                l_a_id <- existing_a$id[1]
                dbExecute(con, "UPDATE assignments SET canvas_name = ?, canvas_group_id = ?, canvas_never_drop = ? WHERE id = ?", params = list(a_name, l_g_id, is_never_drop, l_a_id))
              } else {
                dbExecute(con, "INSERT INTO assignments (course_id, group_id, canvas_assign_id, name, canvas_name, canvas_group_id, scoring_mode, never_drop, canvas_never_drop) VALUES (?, ?, ?, ?, ?, ?, 'negative', ?, ?)", params = list(rv$active_class_id, l_g_id, a_id, a_name, a_name, l_g_id, is_never_drop, is_never_drop))
                l_a_id <- dbGetQuery(con, "SELECT last_insert_rowid()")[[1]]
              }
              
              q_check <- dbGetQuery(con, "SELECT id FROM questions WHERE assignment_id = ? AND title = 'Canvas Sync'", params = list(l_a_id))
              if(nrow(q_check) == 0) {
                dbExecute(con, "INSERT INTO questions (assignment_id, parent_id, title, max_points) VALUES (?, NULL, 'Canvas Sync', ?)", params=list(l_a_id, pts))
              } else {
                dbExecute(con, "UPDATE questions SET max_points = ? WHERE id = ?", params=list(pts, q_check$id[1]))
              }
            }
          }
        }
      }
      
      # 4. Sync Submissions (Grades)
      if (length(c_assigns) > 0 && nrow(c_assigns) > 0) {
        local_students <- dbGetQuery(con, "SELECT id, canvas_user_id FROM students WHERE course_id = ?", params=list(rv$active_class_id))
        local_assigns <- dbGetQuery(con, "SELECT id, canvas_assign_id FROM assignments WHERE course_id = ?", params=list(rv$active_class_id))
        
        for (i in 1:nrow(c_assigns)) {
          c_a_id <- as.character(c_assigns$id[i])
          a_name <- c_assigns$name[i]
          
          # Dynamic alert updating the specific assignment being fetched
          showNotification(paste("Fetching grades for:", a_name, sprintf("(%d/%d)", i, nrow(c_assigns))), id = prog_id)
          
          subs_endpoint <- paste0("courses/", active_class$canvas_id, "/assignments/", c_a_id, "/submissions?per_page=100")
          c_subs <- api_get(subs_endpoint)
          
          if (length(c_subs) > 0 && nrow(c_subs) > 0) {
            for (j in 1:nrow(c_subs)) {
              c_u_id <- as.character(c_subs$user_id[j])
              score <- c_subs$score[j]
              if (is.null(score) || is.na(score)) {
                if("grade" %in% names(c_subs) && !is.na(c_subs$grade[j])) {
                  score <- suppressWarnings(as.numeric(c_subs$grade[j]))
                }
              }
              
              if (is.null(score) || is.na(score)) next
              
              s_idx <- which(local_students$canvas_user_id == c_u_id)
              a_idx <- which(local_assigns$canvas_assign_id == c_a_id)
              
              if (length(s_idx) > 0 && length(a_idx) > 0) {
                l_s_id <- local_students$id[s_idx[1]]
                l_a_id <- local_assigns$id[a_idx[1]]
                
                q_info <- dbGetQuery(con, "SELECT id FROM questions WHERE assignment_id = ? AND title = 'Canvas Sync'", params=list(l_a_id))
                if (nrow(q_info) > 0) {
                  l_q_id <- q_info$id[1]
                  exists_sub <- dbGetQuery(con, "SELECT * FROM subgrades WHERE student_id = ? AND assignment_id = ? AND question_id = ?", params=list(l_s_id, l_a_id, l_q_id))
                  
                  if (nrow(exists_sub) > 0) {
                    dbExecute(con, "UPDATE subgrades SET score = ? WHERE student_id = ? AND assignment_id = ? AND question_id = ?", params=list(score, l_s_id, l_a_id, l_q_id))
