  output$overall_gradebook_table <- renderDT({
    # 1. Fetch Students & Architecture
    students <- dbGetQuery(con, "SELECT id as student_id, sortable_name, nickname FROM students WHERE course_id = ?", params = list(rv$active_class_id))
    assigns <- dbGetQuery(con, "SELECT a.id as assignment_id, a.name, a.group_id, a.never_drop FROM assignments a WHERE a.course_id = ?", params = list(rv$active_class_id))
    groups <- dbGetQuery(con, "SELECT id as group_id, name as group_name, local_weight, drop_lowest FROM assignment_groups WHERE course_id = ?", params = list(rv$active_class_id))
    
    if(nrow(students) == 0) {
      return(datatable(data.frame(Notice = "No students enrolled yet."), rownames = FALSE, options = list(dom = 't', bSort = FALSE)))
    }
    
    # 2. Dynamically Calculate Max Points per Assignment
    qs <- dbGetQuery(con, "
      SELECT a.id as assignment_id, SUM(q.max_points) as max_pts 
      FROM assignments a 
      LEFT JOIN questions q ON a.id = q.assignment_id 
      WHERE a.course_id = ? 
      GROUP BY a.id
    ", params = list(rv$active_class_id))
    
    assigns <- assigns %>% 
      left_join(qs, by = "assignment_id") %>% 
      mutate(max_pts = ifelse(is.na(max_pts), 0, max_pts))
    
    df <- students %>%
      mutate(Student = ifelse(!is.na(nickname) & nickname != "", paste0(sortable_name, ' "', nickname, '"'), sortable_name)) %>%
      select(student_id, Student)
    
    # 3. Fetch Student Subgrades
    grades <- dbGetQuery(con, "
      SELECT s.student_id, s.assignment_id, SUM(s.score) as assign_score 
      FROM subgrades s
      JOIN assignments a ON s.assignment_id = a.id
      WHERE a.course_id = ?
      GROUP BY s.student_id, s.assignment_id
    ", params = list(rv$active_class_id))
    
    if(nrow(grades) > 0 && nrow(assigns) > 0) {
      
      # --- THE MATH ENGINE ---
      graded_data <- grades %>%
        left_join(assigns, by = "assignment_id") %>%
        left_join(groups, by = "group_id") %>%
        filter(max_pts > 0) 
      
      if(nrow(graded_data) > 0) {
        group_avgs <- graded_data %>%
          mutate(pct = assign_score / max_pts) %>%
          group_by(student_id, group_id) %>%
          arrange(student_id, group_id, pct) %>% 
          mutate(
            drop_rank = ifelse(never_drop == 0, cumsum(never_drop == 0), 99999),
            is_dropped = ifelse(never_drop == 0 & drop_rank <= first(drop_lowest), TRUE, FALSE)
          ) %>%
          filter(!is_dropped) %>%
          summarize(
            earned = sum(assign_score),
            possible = sum(max_pts),
            group_pct = earned / possible,
            .groups = "drop"
          ) %>%
          left_join(groups, by = "group_id")
        
        overall <- group_avgs %>%
          group_by(student_id) %>%
          summarize(
            total_weight = sum(local_weight),
            weighted_sum = sum(group_pct * local_weight),
            overall_pct = ifelse(total_weight > 0, weighted_sum / total_weight, 0),
            .groups = "drop"
          ) %>%
          mutate(Overall = sprintf("%.2f%%", overall_pct * 100))
        
        group_wide <- group_avgs %>%
          mutate(group_disp = paste0(group_name, " Avg"), pct_disp = sprintf("%.2f%%", group_pct * 100)) %>%
          select(student_id, group_disp, pct_disp) %>%
          pivot_wider(names_from = group_disp, values_from = pct_disp)
        
        df <- df %>%
          left_join(overall %>% select(student_id, Overall), by = "student_id") %>%
          left_join(group_wide, by = "student_id")
      } else {
        df$Overall <- "---"
      }
      
      # 4. Pivot Individual Assignments Wide (Insert "---" for missing)
      assign_wide <- grades %>%
        left_join(assigns, by = "assignment_id") %>%
        select(student_id, name, assign_score) %>%
        mutate(assign_score = as.character(assign_score)) %>%
        pivot_wider(names_from = name, values_from = assign_score, values_fill = list(assign_score = "---"))
      
      df <- df %>% left_join(assign_wide, by = "student_id")
      
    } else {
      df$Overall <- "---"
    }
    
    # 4.5 Ensure all assignments exist as columns even if no student has a grade yet
    for(a in assigns$name) {
      if(!a %in% names(df)) df[[a]] <- "---"
      df[[a]][is.na(df[[a]])] <- "---"
    }
    
    # Ensure missing overall values show as "---"
    df$Overall[is.na(df$Overall)] <- "---"
    
    df$student_id <- NULL
    
    # 5. Render Advanced Table
    datatable(df, extensions = 'FixedColumns', rownames = FALSE, options = list(
      dom = '<"d-flex justify-content-between align-items-center"lf>rt<"d-flex justify-content-between align-items-center"ip>',
      lengthMenu = list(c(15, 25, 50, 100, -1), c('15', '25', '50', '100', 'All')),
      pageLength = 25, 
      scrollX = TRUE,
      scrollY = "calc(100vh - 445px)",
      scrollCollapse = TRUE,
      paging = TRUE,
      fixedColumns = list(leftColumns = 1), 
      columnDefs = list(
        list(targets = "_all", className = 'dt-nowrap') 
      )
    ))
  })
  
  # --- PAGE 6: ROSTER VIEW ---
  observeEvent(input$view_roster, { rv$page <- "roster_view" })
  observeEvent(input$nav_course_from_roster, { rv$page <- "course_home" })
  
  build_roster_view <- function() {
    active_class <- rv$my_classes[rv$my_classes$id == rv$active_class_id, ]
    is_standalone <- active_class$class_type == "standalone"
    
    add_btn <- if(is_standalone) {
      actionButton("open_add_student", "+ Add Student Manually", icon = icon("user-plus"), style="background-color: #20c997; border: none; color: #12151A; font-weight: bold;")
    } else { p("Students are managed automatically via Canvas sync.", style="color: #8d99ae; font-style: italic; margin: 0;") }
    
    div(class = "p-4 d-flex flex-column", style = "height: 100%; overflow: hidden;",
        div(style = "flex: 0 0 auto;",
            actionLink("nav_course_from_roster", "⬅ Back to Course", style="color: #adb5bd; font-weight: 600; margin-bottom: 20px; display: block;"),
            div(style="display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 20px;",
                h3(paste(active_class$custom_name, "- Class Roster"), style="color: white; margin: 0; font-weight: 700;"),
                add_btn
            )
        ),
        
        # ADDED min-height: 0; to prevent flexbox blowout
        card(style = "background-color: #1a1d24; border: 1px solid #2a2d35; padding: 15px; border-radius: 8px; flex: 1 1 auto; overflow: hidden; min-height: 0;",
             DTOutput("roster_table", height = "100%")
        )
    )
  }
  
  output$roster_table <- renderDT({
    rv$refresh_roster
    active_class <- rv$my_classes[rv$my_classes$id == rv$active_class_id, ]
    is_standalone <- active_class$class_type == "standalone"
    
    students <- dbGetQuery(con, "SELECT id, sortable_name, nickname, notes FROM students WHERE course_id = ?", params=list(rv$active_class_id))
    
    if(nrow(students) == 0) {
      return(datatable(data.frame(Notice="No students found."), rownames=FALSE, options=list(dom='t', bSort=FALSE)))
    }
    
    df <- students %>%
      mutate(
        display_name = ifelse(!is.na(nickname) & nickname != "", paste0(sortable_name, ' "', nickname, '"'), sortable_name),
        notes = ifelse(is.na(notes), "", notes),
        Actions = sapply(id, function(sid) {
          edit_btn <- sprintf('<button class="btn btn-sm" style="background:transparent; color:#20c997; border:none; margin-right:5px;" onclick="Shiny.setInputValue(\'edit_student_id\', %d, {priority:\'event\'})"><i class="fa fa-pen"></i></button>', sid)
          del_btn <- if(is_standalone) sprintf('<button class="btn btn-sm" style="background:transparent; color:#dc3545; border:none;" onclick="Shiny.setInputValue(\'del_student_id\', %d, {priority:\'event\'})"><i class="fa fa-trash"></i></button>', sid) else ""
          paste(edit_btn, del_btn)
        })
      ) %>%
      select(Student = display_name, Notes = notes, Actions)
    
    datatable(df, escape = FALSE, selection = "none", rownames = FALSE, options = list(
      # Wraps Length (l) and Filter (f) in a flex row, and Info (i) and Pagination (p) in a flex row
      dom = '<"d-flex justify-content-between align-items-center"lf>rt<"d-flex justify-content-between align-items-center"ip>',
      lengthMenu = list(c(15, 25, 50, 100, -1), c('15', '25', '50', '100', 'All')),
      pageLength = 25, 
      scrollY = "calc(100vh - 420px)", 
      scrollCollapse = TRUE,
      language = list(search = "Search Roster:", searchPlaceholder = "Name or Note...", lengthMenu = "Show _MENU_ students")
    ))
  })
  
  # --- ROSTER CRUD LOGIC ---
  # Add (Standalone Only)
  observeEvent(input$open_add_student, {
    showModal(modalDialog(
      title = "Add Student",
      textInput("new_stu_name", "Full Name (Last, First):"),
      textInput("new_stu_nick", "Nickname (Optional):"),
      textAreaInput("new_stu_notes", "Private Notes (Optional):", rows = 2),
      footer = tagList(modalButton("Cancel"), actionButton("save_new_stu", "Add Student", class="btn-success"))
    ))
  })
  
  observeEvent(input$save_new_stu, {
    req(input$new_stu_name)
    dbExecute(con, "INSERT INTO students (course_id, sortable_name, nickname, notes) VALUES (?, ?, ?, ?)", 
              params = list(rv$active_class_id, input$new_stu_name, input$new_stu_nick, input$new_stu_notes))
    rv$refresh_roster <- rv$refresh_roster + 1
    removeModal()
  })
  
  # Edit Modal (Fired from JS in the DT)
  observeEvent(input$edit_student_id, {
    s_id <- input$edit_student_id
    rv$student_to_edit <- s_id
    curr <- dbGetQuery(con, "SELECT * FROM students WHERE id = ?", params=list(s_id))
    active_class <- rv$my_classes[rv$my_classes$id == rv$active_class_id, ]
    is_standalone <- active_class$class_type == "standalone"
    
    showModal(modalDialog(
      title = "Edit Student Profile",
      # Only allow name editing if it's a standalone course
      if(is_standalone) textInput("edit_stu_name", "Official Name:", value=curr$sortable_name) else div(h6("Official Name (Managed by Canvas):", style="color:#adb5bd;"), h5(curr$sortable_name, style="color:white; margin-bottom:20px;")),
      textInput("edit_stu_nick", "Preferred Nickname:", value=curr$nickname),
      textAreaInput("edit_stu_notes", "Private Instructor Notes:", value=curr$notes, rows=3),
      footer = tagList(modalButton("Cancel"), actionButton("save_edit_stu", "Save Profile", class="btn-success"))
    ))
  })
  
  observeEvent(input$save_edit_stu, {
    req(rv$student_to_edit)
    active_class <- rv$my_classes[rv$my_classes$id == rv$active_class_id, ]
    
    if(active_class$class_type == "standalone") {
      req(input$edit_stu_name)
      dbExecute(con, "UPDATE students SET sortable_name = ?, nickname = ?, notes = ? WHERE id = ?", 
                params = list(input$edit_stu_name, input$edit_stu_nick, input$edit_stu_notes, rv$student_to_edit))
    } else {
      # Canvas course - update everything EXCEPT the official name
      dbExecute(con, "UPDATE students SET nickname = ?, notes = ? WHERE id = ?", 
                params = list(input$edit_stu_nick, input$edit_stu_notes, rv$student_to_edit))
    }
    rv$refresh_roster <- rv$refresh_roster + 1
    rv$student_to_edit <- NULL
    removeModal()
  })
  
  # Delete (Standalone Only)
  observeEvent(input$del_student_id, {
    rv$student_to_delete <- input$del_student_id
    showModal(modalDialog(
      title = "Remove Student",
      "Are you sure you want to remove this student? All of their subgrades will be permanently deleted.",
      footer = tagList(modalButton("Cancel"), actionButton("confirm_del_stu", "Yes, Remove", class="btn-danger"))
    ))
  })
  
  observeEvent(input$confirm_del_stu, {
    req(rv$student_to_delete)
    dbExecute(con, "DELETE FROM subgrades WHERE student_id = ?", params = list(rv$student_to_delete))
    dbExecute(con, "DELETE FROM students WHERE id = ?", params = list(rv$student_to_delete))
    rv$refresh_roster <- rv$refresh_roster + 1
    rv$student_to_delete <- NULL
    removeModal()
  })
  
  
}

